`;

import { DatabaseSync } from "node:sqlite";
import fs from "node:fs";
import path from "node:path";
import { INITIAL_SCHEMA } from "./schema.js";

export class DatabaseManager {
  private db: DatabaseSync | null = null;
  private dbPath: string;

  constructor(dbPath: string = process.env.DATABASE_PATH || "./data/cardeal.db") {
    this.dbPath = dbPath;
  }

  public getDatabase(): DatabaseSync {
    if (!this.db) {
      if (this.dbPath !== ":memory:") {
        const dir = path.dirname(this.dbPath);
        if (!fs.existsSync(dir)) {
          fs.mkdirSync(dir, { recursive: true });
        }
      }
      this.db = new DatabaseSync(this.dbPath);
      // Enable WAL mode and foreign keys for file-backed DBs
      if (this.dbPath !== ":memory:") {
        this.db.exec("PRAGMA journal_mode = WAL;");
      }
      this.db.exec("PRAGMA foreign_keys = ON;");
      this.runMigrations();
    }
    return this.db;
  }

  public runMigrations(): void {
    if (!this.db) {
      throw new Error("Database not initialized");
    }
    this.db.exec(INITIAL_SCHEMA);
  }

  public close(): void {
    if (this.db) {
      this.db.close();
      this.db = null;
    }
  }

  public getPath(): string {
    return this.dbPath;
  }
}

let defaultManager: DatabaseManager | null = null;

export function getDatabaseManager(customPath?: string): DatabaseManager {
  if (customPath) {
    return new DatabaseManager(customPath);
  }
  if (!defaultManager) {
    defaultManager = new DatabaseManager();
  }
  return defaultManager;
}

export function resetDefaultDatabaseManager(): void {
  if (defaultManager) {
    defaultManager.close();
    defaultManager = null;
  }
}

import crypto from "node:crypto";
import { promisify } from "node:util";

const scryptAsync = promisify(crypto.scrypt);

export class PasswordService {
  private static readonly KEY_LEN = 64;
  private static readonly SALT_LEN = 32;

  public static async hash(password: string): Promise<string> {
    const salt = crypto.randomBytes(this.SALT_LEN).toString("hex");
    const derivedKey = (await scryptAsync(password, salt, this.KEY_LEN)) as Buffer;
    return `scrypt:${salt}:${derivedKey.toString("hex")}`;
  }

  public static async verify(password: string, hash: string): Promise<boolean> {
    const parts = hash.split(":");
    if (parts.length !== 3 || parts[0] !== "scrypt") {
      return false;
    }
    const [, salt, originalKeyHex] = parts;
    const originalKey = Buffer.from(originalKeyHex, "hex");
    const derivedKey = (await scryptAsync(password, salt, this.KEY_LEN)) as Buffer;
    if (originalKey.length !== derivedKey.length) {
      return false;
    }
    return crypto.timingSafeEqual(originalKey, derivedKey);
  }
}

