import { describe, it, expect, beforeEach, afterEach } from "vitest";
import request from "supertest";
import path from "node:path";
import fs from "node:fs";
import { createApp } from "../src/app.js";
import { DatabaseManager } from "../src/database/connection.js";
import { provisionAdminUser } from "../src/cli/provisionAdmin.js";

describe("TDD Slice 7: Atomic Purchase, Restock and Concurrency", () => {
  const testDbPath = path.resolve("./data/test_purchase_restock.db");
  const testJwtSecret = "a_very_secure_test_jwt_secret_key_at_least_32_characters";
  let dbManager: DatabaseManager;
  let adminToken: string;
  let buyerToken1: string;
  let buyerToken2: string;

  beforeEach(async () => {
    if (fs.existsSync(testDbPath)) {
      fs.unlinkSync(testDbPath);
    }
    dbManager = new DatabaseManager(testDbPath);
    dbManager.getDatabase();

    const app = createApp({ dbManager, jwtSecret: testJwtSecret });

    // Provision admin
    await provisionAdminUser(dbManager, "admin@cardeal.com", "AdminMasterPass123!");
    const adminLoginRes = await request(app)
      .post("/api/auth/login")
      .send({ email: "admin@cardeal.com", password: "AdminMasterPass123!" });
    adminToken = adminLoginRes.body.token;

    // Register Buyer 1
    await request(app)
      .post("/api/auth/register")
      .send({ email: "buyer1@cardeal.com", password: "BuyerOnePassword123!" });
    const buyer1LoginRes = await request(app)
      .post("/api/auth/login")
      .send({ email: "buyer1@cardeal.com", password: "BuyerOnePassword123!" });
    buyerToken1 = buyer1LoginRes.body.token;

    // Register Buyer 2
    await request(app)
      .post("/api/auth/register")
      .send({ email: "buyer2@cardeal.com", password: "BuyerTwoPassword123!" });
    const buyer2LoginRes = await request(app)
      .post("/api/auth/login")
      .send({ email: "buyer2@cardeal.com", password: "BuyerTwoPassword123!" });
    buyerToken2 = buyer2LoginRes.body.token;
  });

  afterEach(() => {
    dbManager.close();
    if (fs.existsSync(testDbPath)) {
      fs.unlinkSync(testDbPath);
    }
  });

  it("decrements quantity by 1 upon valid purchase", async () => {
    const app = createApp({ dbManager, jwtSecret: testJwtSecret });

    const createRes = await request(app)
      .post("/api/vehicles")
      .set("Authorization", `Bearer ${adminToken}`)
      .send({ make: "Mazda", model: "CX-5", category: "SUV", price: 280000000, quantity: 2 });

    const vehicleId = createRes.body.vehicle.id;

    const purchaseRes = await request(app)
      .post(`/api/vehicles/${vehicleId}/purchase`)
      .set("Authorization", `Bearer ${buyerToken1}`)
      .send();

    expect(purchaseRes.status).toBe(200);
    expect(purchaseRes.body.vehicle.quantity).toBe(1);

    // Purchase second unit
    const purchase2Res = await request(app)
      .post(`/api/vehicles/${vehicleId}/purchase`)
      .set("Authorization", `Bearer ${buyerToken1}`)
      .send();

    expect(purchase2Res.status).toBe(200);
    expect(purchase2Res.body.vehicle.quantity).toBe(0);

    // Attempt purchase on 0 stock -> 409 OUT_OF_STOCK
    const purchaseEmptyRes = await request(app)
      .post(`/api/vehicles/${vehicleId}/purchase`)
      .set("Authorization", `Bearer ${buyerToken1}`)
      .send();

    expect(purchaseEmptyRes.status).toBe(409);
    expect(purchaseEmptyRes.body.error.code).toBe("OUT_OF_STOCK");
  });

  it("handles competing requests for the last remaining unit: exactly 1 succeeds, 1 gets 409 conflict", async () => {
    const app = createApp({ dbManager, jwtSecret: testJwtSecret });

    // Vehicle with strictly 1 unit in stock
    const createRes = await request(app)
      .post("/api/vehicles")
      .set("Authorization", `Bearer ${adminToken}`)
      .send({ make: "Porsche", model: "911 GT3", category: "Sports", price: 1500000000, quantity: 1 });

    const vehicleId = createRes.body.vehicle.id;

    // Fire two purchase requests concurrently for the single unit
    const [res1, res2] = await Promise.all([
      request(app)
        .post(`/api/vehicles/${vehicleId}/purchase`)
        .set("Authorization", `Bearer ${buyerToken1}`)
        .send(),
      request(app)
        .post(`/api/vehicles/${vehicleId}/purchase`)
        .set("Authorization", `Bearer ${buyerToken2}`)
        .send()
    ]);

    const statuses = [res1.status, res2.status].sort();
    expect(statuses).toEqual([200, 409]);

    const conflictRes = res1.status === 409 ? res1 : res2;
    expect(conflictRes.body.error.code).toBe("OUT_OF_STOCK");

    // Check final stock in SQLite is 0
    const db = dbManager.getDatabase();
    const finalRow = db.prepare("SELECT quantity FROM vehicles WHERE id = ?").get(vehicleId) as { quantity: number };
    expect(finalRow.quantity).toBe(0);
  });

  it("allows admin to restock with a positive integer increment", async () => {
    const app = createApp({ dbManager, jwtSecret: testJwtSecret });

    const createRes = await request(app)
      .post("/api/vehicles")
      .set("Authorization", `Bearer ${adminToken}`)
      .send({ make: "Hyundai", model: "Creta", category: "SUV", price: 180000000, quantity: 1 });

    const vehicleId = createRes.body.vehicle.id;

    // Restock with +5 units
    const restockRes = await request(app)
      .post(`/api/vehicles/${vehicleId}/restock`)
      .set("Authorization", `Bearer ${adminToken}`)
      .send({ quantity: 5 });

    expect(restockRes.status).toBe(200);
    expect(restockRes.body.vehicle.quantity).toBe(6);

    // Reject non-positive increments
    const negRestockRes = await request(app)
      .post(`/api/vehicles/${vehicleId}/restock`)
      .set("Authorization", `Bearer ${adminToken}`)
      .send({ quantity: -2 });
    expect(negRestockRes.status).toBe(400);
    expect(negRestockRes.body.error.code).toBe("VALIDATION_ERROR");

    // Reject 0 increment
    const zeroRestockRes = await request(app)
      .post(`/api/vehicles/${vehicleId}/restock`)
      .set("Authorization", `Bearer ${adminToken}`)
      .send({ quantity: 0 });
    expect(zeroRestockRes.status).toBe(400);

    // Reject non-admin restock
    const buyerRestockRes = await request(app)
      .post(`/api/vehicles/${vehicleId}/restock`)
      .set("Authorization", `Bearer ${buyerToken1}`)
      .send({ quantity: 3 });
    expect(buyerRestockRes.status).toBe(403);
  });
});

import crypto from "node:crypto";
import { DatabaseManager } from "../database/connection.js";

export interface Vehicle {
  id: string;
  make: string;
  model: string;
  category: string;
  price: number;
  quantity: number;
  created_at: string;
  updated_at: string;
}

export interface CreateVehicleInput {
  make: unknown;
  model: unknown;
  category: unknown;
  price: unknown;
  quantity: unknown;
}

export interface UpdateVehicleInput {
  make: unknown;
  model: unknown;
  category: unknown;
  price: unknown;
  quantity?: unknown;
}

export interface SearchVehicleQuery {
  make?: unknown;
  model?: unknown;
  category?: unknown;
  minPrice?: unknown;
  maxPrice?: unknown;
}

export class VehicleService {
  private dbManager: DatabaseManager;

  constructor(dbManager: DatabaseManager) {
    this.dbManager = dbManager;
  }

  private validateTextField(val: unknown, fieldName: string): string {
    if (typeof val !== "string" || val.trim().length === 0 || val.trim().length > 100) {
      const err = new Error(`${fieldName} must be a non-empty string between 1 and 100 characters.`);
      (err as any).statusCode = 400;
      (err as any).code = "VALIDATION_ERROR";
      throw err;
    }
    return val.trim();
  }

  private validateNonNegativeInteger(val: unknown, fieldName: string): number {
    if (typeof val !== "number" || !Number.isInteger(val) || val < 0) {
      const err = new Error(`${fieldName} must be a non-negative integer.`);
      (err as any).statusCode = 400;
      (err as any).code = "VALIDATION_ERROR";
      throw err;
    }
    return val;
  }

  private escapeLike(str: string): string {
    return str.replace(/\\/g, "\\\\").replace(/%/g, "\\%").replace(/_/g, "\\_");
  }

  public async create(input: CreateVehicleInput): Promise<Vehicle> {
    const make = this.validateTextField(input.make, "make");
    const model = this.validateTextField(input.model, "model");
    const category = this.validateTextField(input.category, "category");
    const price = this.validateNonNegativeInteger(input.price, "price");
    const quantity = this.validateNonNegativeInteger(input.quantity, "quantity");

    const id = crypto.randomUUID();
    const now = new Date().toISOString();

    const db = this.dbManager.getDatabase();
    const stmt = db.prepare(
      "INSERT INTO vehicles (id, make, model, category, price, quantity, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)"
    );
    stmt.run(id, make, model, category, price, quantity, now, now);

    return {
      id,
      make,
      model,
      category,
      price,
      quantity,
      created_at: now,
      updated_at: now
    };
  }

  public async list(): Promise<Vehicle[]> {
    const db = this.dbManager.getDatabase();
    const stmt = db.prepare("SELECT * FROM vehicles ORDER BY created_at DESC, id ASC");
    return stmt.all() as Vehicle[];
  }

  public async getById(id: string): Promise<Vehicle> {
    const db = this.dbManager.getDatabase();
    const stmt = db.prepare("SELECT * FROM vehicles WHERE id = ?");
    const vehicle = stmt.get(id) as Vehicle | undefined;
    if (!vehicle) {
      const err = new Error("Vehicle not found.");
      (err as any).statusCode = 404;
      (err as any).code = "VEHICLE_NOT_FOUND";
      throw err;
    }
    return vehicle;
  }

  public async update(id: string, input: UpdateVehicleInput): Promise<Vehicle> {
    if (input.quantity !== undefined) {
      const err = new Error("Vehicle quantity cannot be modified via PUT. Use restock or purchase endpoints.");
      (err as any).statusCode = 400;
      (err as any).code = "VALIDATION_ERROR";
      throw err;
    }

    const make = this.validateTextField(input.make, "make");
    const model = this.validateTextField(input.model, "model");
    const category = this.validateTextField(input.category, "category");
    const price = this.validateNonNegativeInteger(input.price, "price");

    await this.getById(id);

    const now = new Date().toISOString();
    const db = this.dbManager.getDatabase();
    const stmt = db.prepare(
      "UPDATE vehicles SET make = ?, model = ?, category = ?, price = ?, updated_at = ? WHERE id = ?"
    );
    stmt.run(make, model, category, price, now, id);

    return this.getById(id);
  }

  public async delete(id: string): Promise<void> {
    await this.getById(id);
    const db = this.dbManager.getDatabase();
    const stmt = db.prepare("DELETE FROM vehicles WHERE id = ?");
    stmt.run(id);
  }

  public async search(query: SearchVehicleQuery): Promise<Vehicle[]> {
    let sql = "SELECT * FROM vehicles WHERE 1=1";
    const params: unknown[] = [];

    if (typeof query.make === "string" && query.make.trim().length > 0) {
      sql += " AND make LIKE ? ESCAPE '\\'";
      params.push(`%${this.escapeLike(query.make.trim())}%`);
    }

    if (typeof query.model === "string" && query.model.trim().length > 0) {
      sql += " AND model LIKE ? ESCAPE '\\'";
      params.push(`%${this.escapeLike(query.model.trim())}%`);
    }

    if (typeof query.category === "string" && query.category.trim().length > 0) {
      sql += " AND LOWER(category) = LOWER(?)";
      params.push(query.category.trim());
    }

    let minPriceNum: number | undefined;
    if (query.minPrice !== undefined && query.minPrice !== "") {
      const num = Number(query.minPrice);
      if (!Number.isInteger(num) || num < 0) {
        const err = new Error("minPrice must be a non-negative integer paise value.");
        (err as any).statusCode = 400;
        (err as any).code = "VALIDATION_ERROR";
        throw err;
      }
      minPriceNum = num;
      sql += " AND price >= ?";
      params.push(minPriceNum);
    }

    let maxPriceNum: number | undefined;
    if (query.maxPrice !== undefined && query.maxPrice !== "") {
      const num = Number(query.maxPrice);
      if (!Number.isInteger(num) || num < 0) {
        const err = new Error("maxPrice must be a non-negative integer paise value.");
        (err as any).statusCode = 400;
        (err as any).code = "VALIDATION_ERROR";
        throw err;
      }
      maxPriceNum = num;
      sql += " AND price <= ?";
      params.push(maxPriceNum);
    }

    if (minPriceNum !== undefined && maxPriceNum !== undefined && minPriceNum > maxPriceNum) {
      const err = new Error("minPrice cannot be greater than maxPrice.");
      (err as any).statusCode = 400;
      (err as any).code = "VALIDATION_ERROR";
      throw err;
    }

    sql += " ORDER BY created_at DESC, id ASC";

    const db = this.dbManager.getDatabase();
    const stmt = db.prepare(sql);
    return stmt.all(...params) as Vehicle[];
  }

  public async purchase(id: string): Promise<Vehicle> {
    await this.getById(id);

    const now = new Date().toISOString();
    const db = this.dbManager.getDatabase();
    const stmt = db.prepare(
      "UPDATE vehicles SET quantity = quantity - 1, updated_at = ? WHERE id = ? AND quantity > 0"
    );
    const result = stmt.run(now, id);

    if (Number(result.changes) === 0) {
      const err = new Error("This vehicle is out of stock.");
      (err as any).statusCode = 409;
      (err as any).code = "OUT_OF_STOCK";
      throw err;
    }

    return this.getById(id);
  }

  public async restock(id: string, increment: unknown): Promise<Vehicle> {
    await this.getById(id);

    if (typeof increment !== "number" || !Number.isInteger(increment) || increment <= 0 || increment > 1_000_000) {
      const err = new Error("Restock increment must be a positive integer.");
      (err as any).statusCode = 400;
      (err as any).code = "VALIDATION_ERROR";
      throw err;
    }

    const now = new Date().toISOString();
    const db = this.dbManager.getDatabase();
    const stmt = db.prepare(
      "UPDATE vehicles SET quantity = quantity + ?, updated_at = ? WHERE id = ?"
    );
    stmt.run(increment, now, id);

    return this.getById(id);
  }
}

import { Request, Response, NextFunction } from "express";
import { VehicleService } from "../services/vehicleService.js";

export class VehicleController {
  private vehicleService: VehicleService;

  constructor(vehicleService: VehicleService) {
    this.vehicleService = vehicleService;
  }

  public create = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const vehicle = await this.vehicleService.create(req.body);
      res.status(201).json({ vehicle });
    } catch (error) {
      next(error);
    }
  };

  public list = async (_req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const vehicles = await this.vehicleService.list();
      res.status(200).json({ vehicles });
    } catch (error) {
      next(error);
    }
  };

  public search = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const vehicles = await this.vehicleService.search(req.query);
      res.status(200).json({ vehicles });
    } catch (error) {
      next(error);
    }
  };

  public update = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const { id } = req.params;
      const vehicle = await this.vehicleService.update(id, req.body);
      res.status(200).json({ vehicle });
    } catch (error) {
      next(error);
    }
  };

  public delete = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const { id } = req.params;
      await this.vehicleService.delete(id);
      res.status(204).send();
    } catch (error) {
      next(error);
    }
  };

  public purchase = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const { id } = req.params;
      const vehicle = await this.vehicleService.purchase(id);
      res.status(200).json({ vehicle });
    } catch (error) {
      next(error);
    }
  };

  public restock = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const { id } = req.params;
      const vehicle = await this.vehicleService.restock(id, req.body.quantity);
      res.status(200).json({ vehicle });
    } catch (error) {
      next(error);
    }
  };
}

import { Router } from "express";
import { VehicleController } from "../controllers/vehicleController.js";

export interface VehicleRouteMiddleware {
  authenticateToken: any;
  requireAdmin: any;
}

export function createVehicleRoutes(
  vehicleController: VehicleController,
  middleware: VehicleRouteMiddleware
): Router {
  const router = Router();

  // All vehicle routes require authentication
  router.use(middleware.authenticateToken);

  // Search & List
  router.get("/search", vehicleController.search);
  router.get("/", vehicleController.list);

  // Actions
  router.post("/:id/purchase", vehicleController.purchase);
  router.post("/:id/restock", middleware.requireAdmin, vehicleController.restock);

  // Admin mutations
  router.post("/", middleware.requireAdmin, vehicleController.create);
  router.put("/:id", middleware.requireAdmin, vehicleController.update);
  router.delete("/:id", middleware.requireAdmin, vehicleController.delete);

  return router;
}

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import request from "supertest";
import path from "node:path";
import fs from "node:fs";
import { createApp } from "../src/app.js";
import { DatabaseManager } from "../src/database/connection.js";
import { provisionAdminUser } from "../src/cli/provisionAdmin.js";

describe("TDD Verification: Restart Persistence on File-Backed SQLite", () => {
  const testDbPath = path.resolve("./data/test_restart_persistence.db");
  const testJwtSecret = "a_very_secure_test_jwt_secret_key_at_least_32_characters";

  beforeEach(() => {
    if (fs.existsSync(testDbPath)) {
      fs.unlinkSync(testDbPath);
    }
  });

  afterEach(() => {
    if (fs.existsSync(testDbPath)) {
      fs.unlinkSync(testDbPath);
    }
  });

  it("proves file-backed SQLite persists data across complete database and app restarts", async () => {
    // 1. Session 1: Open database, provision admin, register buyer, add vehicle
    let dbManager: DatabaseManager | null = new DatabaseManager(testDbPath);
    await provisionAdminUser(dbManager, "admin@persistent.com", "AdminMasterPass123!");

    let app = createApp({ dbManager, jwtSecret: testJwtSecret });

    const adminLoginRes = await request(app)
      .post("/api/auth/login")
      .send({ email: "admin@persistent.com", password: "AdminMasterPass123!" })
      .expect(200);
    const adminToken = adminLoginRes.body.token;

    await request(app)
      .post("/api/auth/register")
      .send({ email: "buyer@persistent.com", password: "BuyerPassword123!" })
      .expect(201);

    const vehicleRes = await request(app)
      .post("/api/vehicles")
      .set("Authorization", `Bearer ${adminToken}`)
      .send({
        make: "Toyota",
        model: "Land Cruiser",
        category: "SUV",
        price: 2100000000,
        quantity: 2
      })
      .expect(201);
    const vehicleId = vehicleRes.body.vehicle.id;

    // Verify file exists on disk
    expect(fs.existsSync(testDbPath)).toBe(true);

    // 2. Complete shutdown: Close database connection and nullify references
    dbManager.close();
    dbManager = null;

    // 3. Session 2: Reopen the database from the same file on disk
    const reopenedDbManager = new DatabaseManager(testDbPath);
    const reopenedApp = createApp({ dbManager: reopenedDbManager, jwtSecret: testJwtSecret });

    // Login with the previously registered buyer using existing hash on disk
    const buyerLoginRes = await request(reopenedApp)
      .post("/api/auth/login")
      .send({ email: "buyer@persistent.com", password: "BuyerPassword123!" });

    expect(buyerLoginRes.status).toBe(200);
    const buyerToken = buyerLoginRes.body.token;

    // Verify the previously inserted vehicle still exists
    const listRes = await request(reopenedApp)
      .get("/api/vehicles")
      .set("Authorization", `Bearer ${buyerToken}`);

    expect(listRes.status).toBe(200);
    expect(listRes.body.vehicles.length).toBe(1);
    expect(listRes.body.vehicles[0].id).toBe(vehicleId);
    expect(listRes.body.vehicles[0].model).toBe("Land Cruiser");
    expect(listRes.body.vehicles[0].quantity).toBe(2);

    // Purchase a unit on the reopened database
    const purchaseRes = await request(reopenedApp)
      .post(`/api/vehicles/${vehicleId}/purchase`)
      .set("Authorization", `Bearer ${buyerToken}`);

    expect(purchaseRes.status).toBe(200);
    expect(purchaseRes.body.vehicle.quantity).toBe(1);

    reopenedDbManager.close();
  });
});

import dotenv from "dotenv";
