import { Request, Response, NextFunction } from "express";
import jwt from "jsonwebtoken";

export interface AuthenticatedUser {
  id: string;
  email: string;
  role: "user" | "admin";
}

declare global {
  namespace Express {
    interface Request {
      user?: AuthenticatedUser;
    }
  }
}

export function createAuthMiddleware(jwtSecret: string) {
  if (!jwtSecret || jwtSecret.trim().length < 32) {
    throw new Error("JWT secret must be explicitly configured with at least 32 characters.");
  }

  const authenticateToken = (req: Request, res: Response, next: NextFunction): void => {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      res.status(401).json({
        error: {
          code: "UNAUTHORIZED",
          message: "Authorization token required."
        }
      });
      return;
    }

    const token = authHeader.substring(7).trim();
    try {
      const decoded = jwt.verify(token, jwtSecret) as { sub: string; email: string; role: "user" | "admin" };
      req.user = {
        id: decoded.sub,
        email: decoded.email,
        role: decoded.role
      };
      next();
    } catch {
      res.status(401).json({
        error: {
          code: "INVALID_TOKEN",
          message: "The provided token is invalid or expired."
        }
      });
    }
  };

  const requireAdmin = (req: Request, res: Response, next: NextFunction): void => {
    if (!req.user || req.user.role !== "admin") {
      res.status(403).json({
        error: {
          code: "FORBIDDEN",
          message: "Administrator privilege required for this action."
        }
      });
      return;
    }
    next();
  };

  return {
    authenticateToken,
    requireAdmin
  };
}

import express, { Express, Request, Response, NextFunction } from "express";
import cors from "cors";
import { DatabaseManager } from "./database/connection.js";
import { AuthService } from "./services/authService.js";
import { AuthController } from "./controllers/authController.js";
import { createAuthRoutes } from "./routes/authRoutes.js";
import { createAuthMiddleware } from "./middleware/authMiddleware.js";
import { VehicleService } from "./services/vehicleService.js";
import { VehicleController } from "./controllers/vehicleController.js";
import { createVehicleRoutes } from "./routes/vehicleRoutes.js";

export interface AppOptions {
  dbManager: DatabaseManager;
  jwtSecret?: string;
  jwtExpiresIn?: string;
}

export function createApp(options: AppOptions): Express {
  const jwtSecret = options.jwtSecret || process.env.JWT_SECRET;
  if (!jwtSecret || jwtSecret.trim().length < 32) {
    throw new Error("JWT secret must be explicitly configured with at least 32 characters. Do not rely on fallback defaults.");
  }
  const jwtExpiresIn = options.jwtExpiresIn || process.env.JWT_EXPIRES_IN || "24h";

  const app = express();

  app.use(cors({
    origin: process.env.CORS_ORIGIN || "http://localhost:5173",
    credentials: true
  }));
  app.use(express.json());

  // Services & Middleware
  const authService = new AuthService(options.dbManager, jwtSecret, jwtExpiresIn);
  const authController = new AuthController(authService);
  const authMiddleware = createAuthMiddleware(jwtSecret);

  const vehicleService = new VehicleService(options.dbManager);
  const vehicleController = new VehicleController(vehicleService);

  // Mount Auth Routes
  const authRouter = createAuthRoutes(authController);
  authRouter.get("/me", authMiddleware.authenticateToken, (req: Request, res: Response) => {
    res.json({ user: req.user });
  });
  app.use("/api/auth", authRouter);

  // Mount Vehicle Routes
  app.use("/api/vehicles", createVehicleRoutes(vehicleController, authMiddleware));

  // Health check endpoint
  app.get("/api/health", (_req: Request, res: Response) => {
    res.json({ status: "ok" });
  });

  // Central error handler matching BACKEND.md contract
  app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
    const statusCode = typeof err.statusCode === "number" && err.statusCode >= 400 && err.statusCode < 600
      ? err.statusCode
      : 500;

    const code = statusCode === 500 ? "INTERNAL_SERVER_ERROR" : (err.code || "ERROR");
    const message = statusCode === 500 ? "An unexpected error occurred." : (err.message || "An unexpected error occurred.");

    res.status(statusCode).json({
      error: {
        code,
        message
      }
    });
  });

  return app;
}

import dotenv from "dotenv";
dotenv.config();

import { createApp } from "./app.js";
import { getDatabaseManager } from "./database/connection.js";

const PORT = parseInt(process.env.PORT || "4000", 10);
const DATABASE_PATH = process.env.DATABASE_PATH || "./data/cardeal.db";
const JWT_SECRET = process.env.JWT_SECRET;

if (!JWT_SECRET || JWT_SECRET.trim().length < 32) {
  console.error("FATAL: JWT_SECRET environment variable is missing or shorter than 32 characters.");
  console.error("Generate a secure private secret with: openssl rand -hex 32");
  process.exit(1);
}

const JWT_EXPIRES_IN = process.env.JWT_EXPIRES_IN || "24h";

const dbManager = getDatabaseManager(DATABASE_PATH);
dbManager.getDatabase();

const app = createApp({ dbManager, jwtSecret: JWT_SECRET, jwtExpiresIn: JWT_EXPIRES_IN });

const server = app.listen(PORT, () => {
  console.log(`[CarDeal IS Backend] Server running on http://localhost:${PORT}`);
  console.log(`[CarDeal IS Backend] Connected to file-backed SQLite database: ${DATABASE_PATH}`);
});

function handleShutdown(signal: string) {
  console.log(`\n[CarDeal IS Backend] Received ${signal}. Shutting down gracefully...`);
  server.close(() => {
    dbManager.close();
    console.log("[CarDeal IS Backend] Database closed and server terminated.");
    process.exit(0);
  });
}

process.on("SIGINT", () => handleShutdown("SIGINT"));
process.on("SIGTERM", () => handleShutdown("SIGTERM"));

import dotenv from "dotenv";
