import React, { useState, useEffect } from "react";
import { Vehicle } from "../types/vehicle.js";
import { validateRupeeInput, rupeesToPaise, formatPaiseToINR } from "../utils/currency.js";

export type AdminModalMode = "add" | "edit" | "restock" | "delete";

interface AdminModalProps {
  mode: AdminModalMode;
  vehicle: Vehicle | null;
  isOpen: boolean;
  onClose: () => void;
  onSaveAdd: (data: { make: string; model: string; category: string; pricePaise: number; quantity: number }) => Promise<void>;
  onSaveEdit: (id: string, data: { make: string; model: string; category: string; pricePaise: number }) => Promise<void>;
  onSaveRestock: (id: string, increment: number) => Promise<void>;
  onConfirmDelete: (id: string) => Promise<void>;
}

export const AdminModal: React.FC<AdminModalProps> = ({
  mode,
  vehicle,
  isOpen,
  onClose,
  onSaveAdd,
  onSaveEdit,
  onSaveRestock,
  onConfirmDelete
}) => {
  const [make, setMake] = useState("");
  const [model, setModel] = useState("");
  const [category, setCategory] = useState("");
  const [priceRupees, setPriceRupees] = useState("");
  const [quantity, setQuantity] = useState("1");
  const [restockIncrement, setRestockIncrement] = useState("1");
  const [error, setError] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (isOpen) {
      setError(null);
      setIsSubmitting(false);

      if (mode === "edit" && vehicle) {
        setMake(vehicle.make);
        setModel(vehicle.model);
        setCategory(vehicle.category);
        setPriceRupees(String(vehicle.price / 100));
      } else if (mode === "restock") {
        setRestockIncrement("5");
      } else if (mode === "add") {
        setMake("");
        setModel("");
        setCategory("");
        setPriceRupees("");
        setQuantity("1");
      }
    }
  }, [isOpen, mode, vehicle]);

  // Handle ESC key
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isOpen) {
        onClose();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    try {
      setIsSubmitting(true);

      if (mode === "add") {
        if (!make.trim() || !model.trim() || !category.trim()) {
          throw new Error("Make, model, and category are required.");
        }
        const priceErr = validateRupeeInput(priceRupees);
        if (priceErr) throw new Error(priceErr);

        const qtyNum = parseInt(quantity, 10);
        if (isNaN(qtyNum) || qtyNum < 0 || !Number.isSafeInteger(qtyNum)) {
          throw new Error("Quantity must be a non-negative integer.");
        }

        const pricePaise = rupeesToPaise(priceRupees);
        await onSaveAdd({
          make: make.trim(),
          model: model.trim(),
          category: category.trim(),
          pricePaise,
          quantity: qtyNum
        });
        onClose();
      } else if (mode === "edit" && vehicle) {
        if (!make.trim() || !model.trim() || !category.trim()) {
          throw new Error("Make, model, and category are required.");
        }
        const priceErr = validateRupeeInput(priceRupees);
        if (priceErr) throw new Error(priceErr);

        const pricePaise = rupeesToPaise(priceRupees);
        await onSaveEdit(vehicle.id, {
          make: make.trim(),
          model: model.trim(),
          category: category.trim(),
          pricePaise
        });
        onClose();
      } else if (mode === "restock" && vehicle) {
        const incrementNum = parseInt(restockIncrement, 10);
        if (isNaN(incrementNum) || incrementNum <= 0 || !Number.isSafeInteger(incrementNum)) {
          throw new Error("Restock increment must be a positive integer.");
        }
        await onSaveRestock(vehicle.id, incrementNum);
        onClose();
      } else if (mode === "delete" && vehicle) {
        await onConfirmDelete(vehicle.id);
        onClose();
      }
    } catch (err: any) {
      setError(err.message || "Failed to complete operation.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-primary/40 backdrop-blur-sm"
      role="dialog"
      aria-modal="true"
      aria-labelledby="admin-modal-title"
    >
      <div className="bg-surface rounded-card border border-border w-full max-w-lg p-6 shadow-xl animate-in fade-in zoom-in-95 duration-150">
        <div className="flex items-center justify-between pb-3 mb-4 border-b border-border">
          <h2 id="admin-modal-title" className="text-lg font-bold text-primary tracking-tight">
            {mode === "add" && "Add New Vehicle to Catalog"}
            {mode === "edit" && `Edit Vehicle Details (${vehicle?.make} ${vehicle?.model})`}
            {mode === "restock" && `Restock Units (${vehicle?.make} ${vehicle?.model})`}
            {mode === "delete" && "Confirm Vehicle Deletion"}
          </h2>
          <button
            type="button"
            onClick={onClose}
            className="text-secondary hover:text-primary p-1 rounded-control focus-visible:ring-1"
            aria-label="Close dialog"
          >
            ✕
          </button>
        </div>

        {error && (
          <div className="mb-4 bg-red-50 text-error border border-red-200 rounded-control p-3 text-xs" role="alert">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Add & Edit Form Fields */}
          {(mode === "add" || mode === "edit") && (
            <>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label htmlFor="modal-make" className="block text-xs font-semibold text-primary mb-1">
                    Make / Brand
                  </label>
                  <input
                    id="modal-make"
                    type="text"
                    required
                    value={make}
                    onChange={(e) => setMake(e.target.value)}
                    placeholder="e.g. Toyota"
                    className="w-full px-3 py-1.5 rounded-control border border-border text-sm text-primary focus:outline-none focus:border-accent focus:ring-1 focus:ring-accent"
                  />
                </div>
                <div>
                  <label htmlFor="modal-model" className="block text-xs font-semibold text-primary mb-1">
                    Model
                  </label>
                  <input
                    id="modal-model"
                    type="text"
                    required
                    value={model}
                    onChange={(e) => setModel(e.target.value)}
                    placeholder="e.g. Camry"
                    className="w-full px-3 py-1.5 rounded-control border border-border text-sm text-primary focus:outline-none focus:border-accent focus:ring-1 focus:ring-accent"
                  />
                </div>
              </div>

              <div>
                <label htmlFor="modal-category" className="block text-xs font-semibold text-primary mb-1">
                  Category
                </label>
                <input
                  id="modal-category"
                  type="text"
                  required
                  value={category}
                  onChange={(e) => setCategory(e.target.value)}
                  placeholder="e.g. Sedan, SUV, Electric, Coupe"
                  className="w-full px-3 py-1.5 rounded-control border border-border text-sm text-primary focus:outline-none focus:border-accent focus:ring-1 focus:ring-accent"
                />
              </div>

              <div>
                <label htmlFor="modal-price" className="block text-xs font-semibold text-primary mb-1">
                  Price in Rupees (₹)
                </label>
                <input
                  id="modal-price"
                  type="text"
                  required
                  value={priceRupees}
                  onChange={(e) => setPriceRupees(e.target.value)}
                  placeholder="e.g. 2500000"
                  className="w-full px-3 py-1.5 rounded-control border border-border text-sm text-primary focus:outline-none focus:border-accent focus:ring-1 focus:ring-accent"
                />
                <span className="text-[11px] text-secondary mt-1 block">
                  Automatically converted and stored in integer paise.
                </span>
              </div>

              {mode === "add" && (
                <div>
                  <label htmlFor="modal-qty" className="block text-xs font-semibold text-primary mb-1">
                    Initial Stock Units
                  </label>
                  <input
                    id="modal-qty"
                    type="number"
                    min="0"
                    required
                    value={quantity}
                    onChange={(e) => setQuantity(e.target.value)}
                    className="w-full px-3 py-1.5 rounded-control border border-border text-sm text-primary focus:outline-none focus:border-accent focus:ring-1 focus:ring-accent"
                  />
                </div>
              )}

              {mode === "edit" && (
                <div className="bg-slate-50 border border-border rounded-control p-3 text-xs text-secondary leading-relaxed">
                  <span className="font-semibold text-primary block mb-0.5">Quantity Excluded:</span>
                  Per project specifications, vehicle stock quantity cannot be edited directly via PUT. Use the Restock or Purchase flows to mutate stock.
                </div>
              )}
            </>
          )}

          {/* Restock Form */}
          {mode === "restock" && vehicle && (
            <div>
              <div className="mb-3 text-xs text-secondary">
                Current Stock: <span className="font-bold text-primary">{vehicle.quantity} units</span> | Price:{" "}
                <span className="font-bold text-primary">{formatPaiseToINR(vehicle.price)}</span>
              </div>
              <label htmlFor="modal-restock-inc" className="block text-xs font-semibold text-primary mb-1">
                Units to Add (+Increment)
              </label>
              <input
                id="modal-restock-inc"
                type="number"
                min="1"
                required
                value={restockIncrement}
                onChange={(e) => setRestockIncrement(e.target.value)}
                className="w-full px-3 py-1.5 rounded-control border border-border text-sm text-primary focus:outline-none focus:border-accent focus:ring-1 focus:ring-accent"
              />
              <span className="text-[11px] text-secondary mt-1 block">
                Stock is incremented atomically.
              </span>
            </div>
          )}

          {/* Delete Form Confirmation */}
          {mode === "delete" && vehicle && (
            <div className="py-2">
              <p className="text-sm text-primary leading-relaxed">
                Are you sure you want to permanently delete{" "}
                <span className="font-bold text-error">
                  {vehicle.make} {vehicle.model}
                </span>{" "}
                (Category: {vehicle.category}, Price: {formatPaiseToINR(vehicle.price)})?
              </p>
              <p className="text-xs text-secondary mt-2">
                This action cannot be undone. The vehicle will be immediately removed from the catalog.
              </p>
            </div>
          )}

          {/* Modal Action Buttons */}
          <div className="pt-3 flex items-center justify-end space-x-3 border-t border-border">
            <button
              type="button"
              onClick={onClose}
              disabled={isSubmitting}
              className="px-4 py-2 rounded-control border border-border text-xs font-semibold text-secondary hover:text-primary transition-colors focus-visible:ring-1"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className={`px-4 py-2 rounded-control text-xs font-semibold text-white tracking-wide transition-colors shadow-sm focus-visible:ring-2 ${
                mode === "delete"
                  ? "bg-error hover:bg-red-700"
                  : "bg-accent hover:bg-accent-hover"
              } disabled:opacity-50`}
            >
              {isSubmitting
                ? "Processing..."
                : mode === "add"
                ? "Save Vehicle"
                : mode === "edit"
                ? "Update Details"
                : mode === "restock"
                ? "Confirm Restock"
                : "Delete Vehicle"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useEffect } from "react";

export type ToastType = "success" | "error" | "info";

export interface ToastMessage {
  id: string;
  type: ToastType;
  title: string;
  message: string;
}

interface ToastProps {
  toasts: ToastMessage[];
  onDismiss: (id: string) => void;
}

export const ToastContainer: React.FC<ToastProps> = ({ toasts, onDismiss }) => {
  return (
    <div
      aria-live="polite"
      aria-atomic="true"
      className="fixed bottom-4 right-4 z-50 flex flex-col space-y-2 max-w-sm w-full pointer-events-none"
    >
      {toasts.map((toast) => (
        <ToastItem key={toast.id} toast={toast} onDismiss={onDismiss} />
      ))}
    </div>
  );
};

const ToastItem: React.FC<{ toast: ToastMessage; onDismiss: (id: string) => void }> = ({
  toast,
  onDismiss
}) => {
  useEffect(() => {
    const timer = setTimeout(() => {
      onDismiss(toast.id);
    }, 5000);
    return () => clearTimeout(timer);
  }, [toast.id, onDismiss]);

  const bgStyles =
    toast.type === "success"
      ? "bg-emerald-50 border-emerald-300 text-emerald-950"
      : toast.type === "error"
      ? "bg-red-50 border-red-300 text-red-950"
      : "bg-teal-50 border-teal-300 text-teal-950";

  const badgeStyles =
    toast.type === "success"
      ? "text-emerald-700 font-bold"
      : toast.type === "error"
      ? "text-red-700 font-bold"
      : "text-accent font-bold";

  return (
    <div
      role="status"
      className={`pointer-events-auto border rounded-card p-4 shadow-lg flex items-start justify-between space-x-3 transition-all ${bgStyles}`}
    >
      <div>
        <span className={`text-xs uppercase tracking-wider block ${badgeStyles}`}>
          {toast.title}
        </span>
        <p className="text-xs mt-0.5 leading-relaxed">{toast.message}</p>
      </div>
      <button
        type="button"
        onClick={() => onDismiss(toast.id)}
        className="text-secondary/70 hover:text-primary p-0.5 rounded text-xs focus-visible:ring-1"
        aria-label="Dismiss alert"
      >
        ✕
      </button>
    </div>
  );
};

import React, { useState, useEffect, useRef } from "react";
import { useAuth } from "./context/AuthContext.js";
import { Navbar } from "./components/Navbar.js";
import { AuthView } from "./components/AuthView.js";
import { FilterSidebar } from "./components/FilterSidebar.js";
import { VehicleCard } from "./components/VehicleCard.js";
import { AdminModal, AdminModalMode } from "./components/AdminModal.js";
import { ToastContainer, ToastMessage } from "./components/Toast.js";
import { Vehicle, VehicleFilters } from "./types/vehicle.js";
import { api } from "./api/client.js";

export const AppContent: React.FC = () => {
  const { isAuthenticated, isAdmin } = useAuth();
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [activeFilters, setActiveFilters] = useState<VehicleFilters>({});
  const [isAdminView, setIsAdminView] = useState(false);
  const [purchasingId, setPurchasingId] = useState<string | null>(null);

  // Admin Modal State
  const [adminModalOpen, setAdminModalOpen] = useState(false);
  const [adminModalMode, setAdminModalMode] = useState<AdminModalMode>("add");
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);

  // Toasts
  const [toasts, setToasts] = useState<ToastMessage[]>([]);

  // Prevent stale search responses
  const latestSearchId = useRef(0);

  const addToast = (type: ToastMessage["type"], title: string, message: string) => {
    const id = Math.random().toString(36).substring(2, 9);
    setToasts((prev) => [...prev, { id, type, title, message }]);
  };

  const dismissToast = (id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  };

  const fetchVehicles = async (filters: VehicleFilters = activeFilters) => {
    const searchId = ++latestSearchId.current;
    setIsLoading(true);
    setLoadError(null);

    try {
      const data = await api.searchVehicles(filters);
      // Discard stale responses
      if (searchId === latestSearchId.current) {
        setVehicles(data);
      }
    } catch (err: any) {
      if (searchId === latestSearchId.current) {
        setLoadError(err.message || "Failed to load vehicle catalog.");
      }
    } finally {
      if (searchId === latestSearchId.current) {
        setIsLoading(false);
      }
    }
  };

  useEffect(() => {
    if (isAuthenticated) {
      fetchVehicles();
    }
  }, [isAuthenticated]);

  const handleApplyFilters = (filters: VehicleFilters) => {
    setActiveFilters(filters);
    fetchVehicles(filters);
  };

  const handleClearFilters = () => {
    setActiveFilters({});
    fetchVehicles({});
  };

  // Purchase Flow
  const handlePurchase = async (id: string) => {
    if (purchasingId) return; // Prevent duplicate clicks
    const target = vehicles.find((v) => v.id === id);
    if (!target) return;

    setPurchasingId(id);

    try {
      const updatedVehicle = await api.purchaseVehicle(id);
      setVehicles((prev) =>
        prev.map((v) => (v.id === id ? updatedVehicle : v))
      );
      addToast(
        "success",
        "Purchase Confirmed",
        `Purchased 1 unit of ${target.make} ${target.model}. Remaining stock: ${updatedVehicle.quantity}.`
      );
    } catch (err: any) {
      if (err.code === "OUT_OF_STOCK") {
        addToast(
          "error",
          "Stock Conflict",
          `Unable to purchase ${target.make} ${target.model}. This vehicle is now out of stock.`
        );
        // Refresh catalog to sync latest state
        fetchVehicles();
      } else {
        addToast(
          "error",
          "Purchase Failed",
          err.message || "An error occurred while processing your purchase. Please refresh."
        );
      }
    } finally {
      setPurchasingId(null);
    }
  };

  // Admin Modal Handlers
  const handleOpenAdd = () => {
    setSelectedVehicle(null);
    setAdminModalMode("add");
    setAdminModalOpen(true);
  };

  const handleOpenEdit = (v: Vehicle) => {
    setSelectedVehicle(v);
    setAdminModalMode("edit");
    setAdminModalOpen(true);
  };

  const handleOpenRestock = (v: Vehicle) => {
    setSelectedVehicle(v);
    setAdminModalMode("restock");
    setAdminModalOpen(true);
  };

  const handleOpenDelete = (v: Vehicle) => {
    setSelectedVehicle(v);
    setAdminModalMode("delete");
    setAdminModalOpen(true);
  };

  const handleSaveAdd = async (data: {
    make: string;
    model: string;
    category: string;
    pricePaise: number;
    quantity: number;
  }) => {
    const newVehicle = await api.createVehicle(data);
    setVehicles((prev) => [newVehicle, ...prev]);
    addToast("success", "Vehicle Added", `Added ${newVehicle.make} ${newVehicle.model} to inventory.`);
  };

  const handleSaveEdit = async (
    id: string,
    data: { make: string; model: string; category: string; pricePaise: number }
  ) => {
    const updated = await api.updateVehicle(id, data);
    setVehicles((prev) => prev.map((v) => (v.id === id ? updated : v)));
    addToast("success", "Vehicle Updated", `Updated details for ${updated.make} ${updated.model}.`);
  };

  const handleSaveRestock = async (id: string, increment: number) => {
    const updated = await api.restockVehicle(id, increment);
    setVehicles((prev) => prev.map((v) => (v.id === id ? updated : v)));
    addToast(
      "success",
      "Stock Replenished",
      `Added +${increment} units to ${updated.make} ${updated.model}. Total stock: ${updated.quantity}.`
    );
  };

  const handleConfirmDelete = async (id: string) => {
    const target = vehicles.find((v) => v.id === id);
    await api.deleteVehicle(id);
    setVehicles((prev) => prev.filter((v) => v.id !== id));
    addToast(
      "info",
      "Vehicle Removed",
      `Deleted ${target?.make || "vehicle"} ${target?.model || ""} from inventory.`
    );
  };

  if (!isAuthenticated) {
    return <AuthView />;
  }

  const activeFilterCount = Object.values(activeFilters).filter(Boolean).length;

  return (
    <div className="min-h-screen bg-page text-primary flex flex-col">
      <Navbar
        isAdminView={isAdminView}
        onToggleAdminView={() => setIsAdminView(!isAdminView)}
      />

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header Title Section */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 pb-6 mb-6 border-b border-border">
          <div>
            <h1 className="text-2xl font-bold tracking-tight text-primary">
              {isAdminView ? "Inventory Management" : "Vehicle Inventory"}
            </h1>
            <p className="text-sm text-secondary mt-1">
              {isLoading
                ? "Searching catalog..."
                : `${vehicles.length} vehicle${vehicles.length === 1 ? "" : "s"} ${
                    activeFilterCount > 0 ? "matching filters" : "available"
                  }`}
            </p>
          </div>

          {isAdmin && isAdminView && (
            <button
              type="button"
              onClick={handleOpenAdd}
              className="py-2.5 px-4 rounded-control bg-accent hover:bg-accent-hover text-white text-sm font-semibold tracking-wide transition-colors shadow-sm flex items-center justify-center space-x-1.5 focus-visible:ring-2"
            >
              <span>+ Add New Vehicle</span>
            </button>
          )}
        </div>

        {/* Catalog Main Layout */}
        <div className="flex flex-col lg:flex-row items-start gap-8">
          {/* Filter Sidebar */}
          <FilterSidebar
            onApplyFilters={handleApplyFilters}
            onClearFilters={handleClearFilters}
            activeCount={activeFilterCount}
          />

          {/* Catalog Grid Area */}
          <section className="flex-1 w-full" aria-label="Vehicle Catalog">
            {/* Loading State */}
            {isLoading ? (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {[...Array(6)].map((_, i) => (
                  <div
                    key={i}
                    className="bg-surface border border-border rounded-card p-5 animate-pulse space-y-4"
                  >
                    <div className="h-4 bg-slate-200 rounded w-1/3"></div>
                    <div className="h-6 bg-slate-200 rounded w-2/3"></div>
                    <div className="h-8 bg-slate-200 rounded w-1/2"></div>
                    <div className="h-10 bg-slate-200 rounded w-full pt-4"></div>
                  </div>
                ))}
              </div>
            ) : loadError ? (
              /* Error State */
              <div className="bg-surface border border-red-200 rounded-card p-8 text-center max-w-lg mx-auto">
                <span className="text-3xl mb-2 block">⚠️</span>
                <h3 className="text-lg font-bold text-error mb-2">Unable to Load Vehicles</h3>
                <p className="text-sm text-secondary mb-4">{loadError}</p>
                <button
                  type="button"
                  onClick={() => fetchVehicles()}
                  className="px-4 py-2 bg-accent hover:bg-accent-hover text-white text-xs font-semibold rounded-control transition-colors"
                >
                  Try Again
                </button>
              </div>
            ) : vehicles.length === 0 ? (
              /* Empty State */
              <div className="bg-surface border border-border rounded-card p-12 text-center max-w-md mx-auto">
                <div className="w-12 h-12 rounded-full bg-slate-100 flex items-center justify-center mx-auto mb-3 text-secondary text-xl">
                  🔍
                </div>
                <h3 className="text-base font-bold text-primary mb-1">
                  {activeFilterCount > 0 ? "No Matching Vehicles" : "Inventory is Empty"}
                </h3>
                <p className="text-xs text-secondary mb-4 leading-relaxed">
                  {activeFilterCount > 0
                    ? "No vehicles match the specified search parameters. Try adjusting or clearing your filters."
                    : "There are currently no vehicles registered in the dealership inventory."}
                </p>
                {activeFilterCount > 0 ? (
                  <button
                    type="button"
                    onClick={handleClearFilters}
                    className="px-3.5 py-1.5 rounded-control bg-accent text-white text-xs font-semibold hover:bg-accent-hover transition-colors"
                  >
                    Clear All Filters
                  </button>
                ) : isAdmin ? (
                  <button
                    type="button"
                    onClick={handleOpenAdd}
                    className="px-3.5 py-1.5 rounded-control bg-accent text-white text-xs font-semibold hover:bg-accent-hover transition-colors"
                  >
                    Add First Vehicle
                  </button>
                ) : null}
              </div>
            ) : (
              /* Vehicle Cards Grid */
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {vehicles.map((v) => (
                  <VehicleCard
                    key={v.id}
                    vehicle={v}
                    isAdminView={isAdminView}
                    isPurchasing={purchasingId === v.id}
                    onPurchase={handlePurchase}
                    onEdit={handleOpenEdit}
                    onRestock={handleOpenRestock}
                    onDelete={handleOpenDelete}
                  />
                ))}
              </div>
            )}
          </section>
        </div>
      </main>

      {/* Admin Operations Modal */}
      <AdminModal
        mode={adminModalMode}
        vehicle={selectedVehicle}
        isOpen={adminModalOpen}
        onClose={() => setAdminModalOpen(false)}
        onSaveAdd={handleSaveAdd}
        onSaveEdit={handleSaveEdit}
        onSaveRestock={handleSaveRestock}
        onConfirmDelete={handleConfirmDelete}
      />

      {/* Toast Notifications */}
      <ToastContainer toasts={toasts} onDismiss={dismissToast} />
    </div>
  );
};

