41:     ...options,
42:     headers
43:   });
44: 
45:   if (res.status === 401) {
46:     if (onUnauthorizedCallback) {
47:       onUnauthorizedCallback();
48:     }
49:   }
50: 
51:   if (res.status === 204) {
52:     return {} as T;
53:   }
54: 
55:   let data: any;
