import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const { DatabaseSync } = require("node:sqlite");

const dbPath = path.resolve("./data/screenshot_demo.db");
const screenshotsDir = path.resolve("./docs/screenshots");

if (!fs.existsSync(screenshotsDir)) {
  fs.mkdirSync(screenshotsDir, { recursive: true });
}

if (fs.existsSync(dbPath)) {
  fs.unlinkSync(dbPath);
}

// 1. Seed database
console.log("[1/6] Seeding screenshot database...");
const db = new DatabaseSync(dbPath);
db.exec("PRAGMA journal_mode = WAL;");
db.exec("PRAGMA foreign_keys = ON;");

db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id TEXT PRIMARY KEY,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL CHECK(role IN ('user', 'admin')),
    created_at TEXT NOT NULL
  );
`);

db.exec(`
  CREATE TABLE IF NOT EXISTS vehicles (
    id TEXT PRIMARY KEY,
    make TEXT NOT NULL,
    model TEXT NOT NULL,
    category TEXT NOT NULL,
    price INTEGER NOT NULL CHECK(price >= 0),
    quantity INTEGER NOT NULL CHECK(quantity >= 0),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
`);

// Password hash for AdminPass12345! using scrypt
import crypto from "node:crypto";
async function hashPassword(password) {
  const salt = crypto.randomBytes(16);
  const derivedKey = await new Promise((resolve, reject) => {
    crypto.scrypt(password, salt, 64, (err, key) => (err ? reject(err) : resolve(key)));
  });
  return `${salt.toString("hex")}:${derivedKey.toString("hex")}`;
}

const adminPassHash = await hashPassword("AdminPass12345!");
const now = new Date().toISOString();

db.prepare("INSERT INTO users (id, email, password_hash, role, created_at) VALUES (?, ?, ?, 'admin', ?)").run(
  "admin-1",
  "admin@cardeal.com",
  adminPassHash,
  now
);

const vehicles = [
  { id: "v1", make: "Porsche", model: "911 GT3", category: "Coupe", price: 2750000000, quantity: 1 },
  { id: "v2", make: "Mercedes-Benz", model: "G 63 AMG", category: "SUV", price: 2550000000, quantity: 0 },
  { id: "v3", make: "BMW", model: "M3 Competition", category: "Sedan", price: 1300000000, quantity: 4 },
  { id: "v4", make: "Tesla", model: "Model 3 Long Range", category: "Electric", price: 550000000, quantity: 7 },
  { id: "v5", make: "Toyota", model: "Camry Hybrid", category: "Sedan", price: 410000000, quantity: 3 },
  { id: "v6", make: "Hyundai", model: "Ioniq 5", category: "Electric", price: 460000000, quantity: 5 }
];

const insertVehicle = db.prepare(
  "INSERT INTO vehicles (id, make, model, category, price, quantity, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)"
);
for (const v of vehicles) {
  insertVehicle.run(v.id, v.make, v.model, v.category, v.price, v.quantity, now, now);
}
db.close();
console.log("Database seeded successfully with 6 vehicles and admin user.");

// 2. Start Backend
console.log("[2/6] Starting backend server...");
const backendDir = path.resolve("./backend");
const tsxCli = path.join(backendDir, "node_modules", "tsx", "dist", "cli.mjs");
const backendProcess = spawn(
  process.execPath,
  [tsxCli, path.join(backendDir, "src", "server.ts")],
  {
    cwd: backendDir,
    env: {
      ...process.env,
      PORT: "4000",
      DATABASE_PATH: dbPath,
      JWT_SECRET: "demo_secure_secret_for_screenshots_32_chars!",
      CORS_ORIGIN: "http://localhost:5173"
    },
    stdio: "pipe"
  }
);

backendProcess.stdout.on("data", (d) => process.stdout.write(`[backend] ${d}`));
backendProcess.stderr.on("data", (d) => process.stderr.write(`[backend err] ${d}`));

// 3. Start Frontend
console.log("[3/6] Starting frontend preview/dev server...");
const frontendDir = path.resolve("./frontend");
const viteCli = path.join(frontendDir, "node_modules", "vite", "bin", "vite.js");
const frontendProcess = spawn(
  process.execPath,
  [viteCli, "--port", "5173", "--strictPort"],
  {
    cwd: frontendDir,
    env: { ...process.env },
    stdio: "pipe"
  }
);

frontendProcess.stdout.on("data", (d) => process.stdout.write(`[frontend] ${d}`));
frontendProcess.stderr.on("data", (d) => process.stderr.write(`[frontend err] ${d}`));

async function waitUrl(url, timeoutMs = 15000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    try {
      const res = await fetch(url);
