import fs from "node:fs";
import readline from "node:readline";

async function run() {
  const fileStream = fs.createReadStream(
    "C:\\Users\\Acer\\.gemini\\antigravity\\brain\\e94dbf59-e05a-4f9d-ba8c-635b8b927dcb\\.system_generated\\logs\\transcript_full.jsonl"
  );
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  const turns = [];
  let currentTurn = null;

  for await (const line of rl) {
    if (!line.trim()) continue;
    const obj = JSON.parse(line);

    if (obj.type === "USER_INPUT" || obj.source === "USER_EXPLICIT") {
      if (currentTurn) {
        turns.push(currentTurn);
      }
      currentTurn = {
        promptStep: obj.step_index,
        promptTime: obj.created_at,
        prompt: obj.content,
        responses: []
      };
    } else if (obj.type === "PLANNER_RESPONSE" && obj.content) {
      if (currentTurn) {
        currentTurn.responses.push({
          step: obj.step_index,
          time: obj.created_at,
          content: obj.content
        });
      }
    }
  }
  if (currentTurn) {
    turns.push(currentTurn);
  }

  console.log(`Total user turns: ${turns.length}`);
  for (let i = 0; i < turns.length; i++) {
    const t = turns[i];
    console.log(`\n================ TURN ${i + 1} (Prompt step ${t.promptStep}, ${t.promptTime}) ================`);
    console.log(`Prompt length: ${t.prompt.length}`);
    console.log(`Prompt preview: ${t.prompt.substring(0, 150).replace(/\n/g, " ")}...`);
    console.log(`Responses count with text content: ${t.responses.length}`);
    if (t.responses.length > 0) {
      const lastResp = t.responses[t.responses.length - 1];
      console.log(`Final response step: ${lastResp.step}, length: ${lastResp.content.length}`);
      console.log(`Final response preview: ${lastResp.content.substring(0, 150).replace(/\n/g, " ")}...`);
    }
  }

  // Write detailed output to scratch file
  fs.writeFileSync(
    "C:\\Users\\Acer\\.gemini\\antigravity\\brain\\e94dbf59-e05a-4f9d-ba8c-635b8b927dcb\\scratch\\extracted_turns.json",
    JSON.stringify(turns, null, 2)
  );
}

run();

